                contextId = this.getContextId(client, isTreeDurable);
                const contextInstance = await this.injector.loadPerContext(instance, moduleRef, collection, contextId);
                this.assignServerToProperties(contextInstance, server);
                const scopedMethod = contextInstance[methodName];
                return await scopedMethod?.apply(contextInstance, args);
